mapper.select:
select *
from throw_skill
INNER JOIN skill_content on throw_skill.uuid = skill_content.uuid
and throw_skill.agent_id = #{agentId} and throw_skill.map_id = #{mapId} and
throw_skill.skill_index = #{skillIndex}

    and skill_content.side = #{side}

select *
from throwground_skill as skill
INNER JOIN skill_content as content on skill.uuid = content.uuid
and skill.agent_id = #{agentId} and skill.map_id = #{mapId} and
skill.skill_index = #{skillIndex}

    and content.side = #{side}

select *
from line_skill as line
INNER JOIN skill_content as content on line.uuid = content.uuid
and line.map_id = #{mapId} and line.agent_id = #{agentId} and line.skill_index = #{skillIndex}

    and content.side=#{side}

select *
from line_skill as line
INNER JOIN skill_collect as collect on line.uuid = collect.skill_uuid
and line.map_id = #{mapId} and line.agent_id=#{agentId} and line.skill_index = #{skillIndex}
INNER JOIN skill_content as content on content.uuid = line.uuid

    and content.side=#{side}

select *, point_list
from control_skill as control
INNER JOIN skill_content as content on control.uuid = content.uuid
and control.map_id = #{mapId} and control.agent_id = #{agentId} and control.skill_index = #{skillIndex}

    and content.side=#{side}

select *
from control_skill as control
INNER JOIN skill_collect as collect on control.uuid = collect.skill_uuid
and control.map_id = #{mapId} and control.agent_id=#{agentId} and control.skill_index = #{skillIndex}
INNER JOIN skill_content as content on content.uuid = control.uuid

    and content.side=#{side}
